import React, { useState } from 'react';
import { Button } from "@/components/ui/button";
import { Sparkles, Loader2, RefreshCw } from 'lucide-react';

export default function TraceReflection({ belief, onSave }) {
  const [isLoading, setIsLoading] = useState(false);
  const [reflection, setReflection] = useState(null);
  const [error, setError] = useState(null);

  const generateReflection = async () => {
    setIsLoading(true);
    setError(null);

    const beliefContent =
      belief?.statement ||
      belief?.content ||
      belief?.text ||
      belief?.thought ||
      belief?.message ||
      belief?.description;

    if (!beliefContent) {
      setError("No belief content found. Please make sure the belief has content.");
      setIsLoading(false);
      return;
    }

    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 30000);

      const response = await fetch(
        "https://api.together.xyz/v1/chat/completions",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${process.env.REACT_APP_TOGETHER_API_KEY}`,
          },
          body: JSON.stringify({
            model: "meta-llama/Meta-Llama-3.1-8B-Instruct-Turbo",
            temperature: 0.7,
            messages: [
              {
                role: "user",
                content: `Please provide a brief, gentle reflection that:
1. Summarizes their belief in neutral language (1-2 sentences)
2. Asks 1-2 clarifying questions that might help them think deeper
3. Gently highlights any assumptions you notice (if any)

Keep your tone warm, curious, and non-judgmental. Be concise — this is for mobile reading. Do not try to change their mind or offer your own opinion.

Belief: ${beliefContent}`,
              },
            ],
          }),
          signal: controller.signal,
        }
      );

      clearTimeout(timeoutId);

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      const data = await response.json();
      const reflectionContent =
        data?.choices?.[0]?.message?.content || "Reflection unavailable";

      setReflection(reflectionContent);
    } catch (err) {
      if (err.name === "AbortError") {
        setError("Request timed out. Please try again.");
      } else {
        console.error(err);
        setError("Couldn't generate reflection. Please try again.");
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    // Try to save current reflection first, then fall back to last saved
    let reflectionToSave = reflection;

    // If no current reflection, use the last saved one
    if (!reflectionToSave && belief?.ai_reflections?.length > 0) {
      reflectionToSave = belief.ai_reflections[belief.ai_reflections.length - 1].content;
    }

    if (!reflectionToSave) return;

    const newAiReflection = {
      date: new Date().toISOString(),
      content: reflectionToSave, // Use the available reflection
    };

    await onSave({
      ai_reflections: [newAiReflection], // overwrite old
    });

    // Clear current reflection state to trigger saved view
    setReflection(null);
  };

  /* ===========================
     LOADING STATE
  =========================== */

  if (isLoading) {
    return (
      <div className="bg-gradient-to-br from-[#E8EDE9] to-[#f0f4f1] rounded-2xl p-6">
        <div className="flex items-center justify-center gap-3 py-8">
          <Loader2 className="w-5 h-5 animate-spin text-[#5C6B5E]" />
          <span className="text-slate-600">Thinking gently...</span>
        </div>
      </div>
    );
  }

  /* ===========================
     ERROR STATE
  =========================== */

  if (error) {
    return (
      <div className="bg-red-50 rounded-2xl p-6">
        <p className="text-red-600 text-sm mb-3">{error}</p>
        <Button
          onClick={generateReflection}
          variant="outline"
          size="sm"
          className="text-red-600 border-red-200"
        >
          <RefreshCw className="w-4 h-4 mr-2" />
          Try again
        </Button>
      </div>
    );
  }

  /* ===========================
     SAVED REFLECTION VIEW
  =========================== */

  // Only show if there are saved reflections
  if (belief?.ai_reflections?.length > 0) {
    const savedReflection = belief.ai_reflections[0]; // Get the last saved reflection
    return (
      <div className="bg-gradient-to-br from-[#E8EDE9] to-[#f0f4f1] rounded-2xl p-6 space-y-4 mb-6">
        <div className="flex items-start gap-3">
          <div className="w-10 h-10 rounded-xl bg-white/80 flex items-center justify-center flex-shrink-0">
            <Sparkles className="w-5 h-5 text-[#5C6B5E]" />
          </div>
          <div className="flex-1">
            <h3 className="font-medium text-slate-800 mb-1">
              <span className="text-sm font-medium text-[#5C6B5E]">Trace Reflection</span>
            </h3>
            <div className="prose prose-slate max-w-none">
              <p className="text-xs text-slate-400 mb-2">
                {new Date(savedReflection.date).toLocaleDateString()}
              </p>
              <p>{savedReflection.content}</p>
            </div>

            <div className="flex gap-2 pt-4">
              <Button
                onClick={generateReflection}
                variant="outline"
                size="sm"
                className="text-slate-600 border-slate-200 rounded-lg"
              >
                <RefreshCw className="w-4 h-4 mr-2" />
                New reflection
              </Button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // Show current unsaved reflection with save option
  if (reflection) {
    return (
      <div className="bg-gradient-to-br from-[#E8EDE9] to-[#f0f4f1] rounded-2xl p-6 space-y-4">
        <div className="flex items-start gap-3">
          <div className="w-10 h-10 rounded-xl bg-white/80 flex items-center justify-center flex-shrink-0">
            <Sparkles className="w-5 h-5 text-[#5C6B5E]" />
          </div>
          <div className="flex-1">
            <h3 className="font-medium text-slate-800 mb-1">
              <span className="text-sm font-medium text-[#5C6B5E]">Trace Reflection</span>
            </h3>
            <div className="prose prose-slate max-w-none">
              <p>{reflection}</p>
            </div>

            <div className="flex gap-2 pt-4">
              <Button
                onClick={generateReflection}
                variant="outline"
                size="sm"
                className="text-slate-600 border-slate-200 rounded-lg"
              >
                <RefreshCw className="w-4 h-4 mr-2" />
                New reflection
              </Button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  /* ===========================
     INITIAL STATE (NO REFLECTION)
  =========================== */

  return (
    <div className="bg-gradient-to-br from-[#E8EDE9] to-[#f0f4f1] rounded-2xl p-6">
      <div className="flex items-start gap-3">
        <div className="w-10 h-10 rounded-xl bg-white/80 flex items-center justify-center flex-shrink-0">
          <Sparkles className="w-5 h-5 text-[#5C6B5E]" />
        </div>

        <div className="flex-1">
          <h3 className="font-medium text-slate-800 mb-1">
            Trace Reflection
          </h3>

          <p className="text-sm text-slate-600 mb-4">
            Get a gentle reflection to help clarify your thinking. Trace won't
            judge or try to change your mind.
          </p>

          <div className="flex gap-2">
            <Button
              onClick={generateReflection}
              className="bg-white hover:bg-slate-50 text-[#5C6B5E] border border-[#5C6B5E]/20 rounded-xl"
            >
              <Sparkles className="w-4 h-4 mr-2" />
              Reflect with Trace
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}
